    10	export type { Item, Customer };
    11	export type { Incident, Damage } from "./claims.js";
    12	
    13	/** A policy MHPCO has written: what it covers and what it was quoted for. */
    14	export interface Policy {
    15	  readonly premium: number;
    16	  readonly insuranceSum: number;
    17	  readonly items: readonly Item[];
    18	  /** What the office may still pay out on this policy. */
    19	  readonly remainingCap: number;
    20	}
    21	
    22	/**
    23	 * The settlement of one claim: what MHPCO pays, and the policy as it stands
    24	 * afterwards — a claim consumes part of the cap, so later claims against the
    25	 * same policy are settled against what is left.
    26	 */
    27	export interface Settlement {
    28	  readonly payout: number;
    29	  /**
    30	   * What the office may still pay out, reported alongside the payout because
    31	   * the claim result states it. The policy carried forward is the one record of
    32	   * that fact; this field only repeats it for the caller's convenience.
    33	   */
    34	  readonly remainingCap: number;
    35	  readonly policy: Policy;
    36	}
    37	
    38	/**
    39	 * Writes a policy for the items the customer wishes to insure: the premium they
    40	 * owe, and the insurance sum the office's payouts are measured against.
    41	 */
    42	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
    43	  const insuranceSum = policyInsuranceSum(items);
    44	  return {
    45	    premium: quote(customer, items),
    46	    insuranceSum,
    47	    items,
    48	    remainingCap: payoutCap(insuranceSum),
    49	  };
    50	}
    51	
    52	/**
    53	 * Settles a damage report against a policy MHPCO has written, in the order the
    54	 * office settles it: what the report's damages come to under the reimbursement
    55	 * clauses, held down to what the policy's cap still allows, and rounded once at
    56	 * the end — the amount that actually leaves the office is the final payout, so
    57	 * the office's favour is taken on that and not on the uncapped total.
    58	 *
    59	 * Each of those rulings is made elsewhere; this function only knows their order.
    60	 */
    61	export function claim(policy: Policy, incident: Incident): Settlement {
    62	  const owed = incidentReimbursement(incident, coverageOf(policy.items));
    63	  const capped = capPayout(owed, policy.remainingCap);
    64	  const settledPolicy: Policy = { ...policy, remainingCap: capped.remainingCap };
    65	  return {
    66	    payout: roundPayoutInMHPCOFavour(capped.payout),
    67	    remainingCap: settledPolicy.remainingCap,
    68	    policy: settledPolicy,
    69	  };
    70	}
    71	
    72	/** MHPCO adds a flat processing fee to every premium, at the very end. */
    73	const PROCESSING_FEE_G = 5;
    74	
    75	/**
    76	 * Assembles the bill in the order the office bills it: the price-list base
    77	 * premium of the policy, the risk surcharges its individual items carry, the
    78	 * modifiers rated on the policy as a whole, and finally the processing fee.
    79	 *
    80	 * Each of those amounts is ruled on elsewhere; this function only knows the
    81	 * order they are applied in and that the total is rounded once, at the end.
    82	 */
    83	export function quote(customer: Customer, items: readonly Item[]): number {
    84	  const policyBase = policyBasePremium(items);
    85	  const premium =
    86	    policyBase +
    87	    itemRiskSurcharges(items) +
    88	    policyModifiers(customer, policyBase) +
    89	    PROCESSING_FEE_G;
    90	  return roundPremiumInMHPCOFavour(premium);
    91	}
