     1	/**
     2	 * How MHPCO settles a damage report against a policy.
     3	 *
     4	 * This module owns the office's claims rulings: what it deducts from every
     5	 * damage event and what it is willing to reimburse. It knows nothing about
     6	 * premiums — a policy costs what it costs, and a claim pays what it pays.
     7	 */
     8	
     9	import { type Item } from "./item.js";
    10	
    11	/** A single damaged item in a damage report. */
    12	export interface Damage {
    13	  readonly itemType: string;
    14	  readonly amount: number;
    15	}
    16	
    17	/** A damage report submitted against a policy. */
    18	export interface Incident {
    19	  readonly cause: string;
    20	  readonly damages: readonly Damage[];
    21	}
    22	
    23	/** MHPCO reimburses the whole damage amount when no clause reduces it. */
    24	const FULL_SHARE = 1;
    25	const HALF_SHARE = 0.5;
    26	
    27	/**
    28	 * A reimbursement clause: a property of a damaged item the office has ruled on,
    29	 * and the share of the damage amount that clause grants.
    30	 */
    31	interface ReimbursementClause {
    32	  readonly appliesTo: (damagedItem: Item) => boolean;
    33	  readonly share: number;
    34	}
    35	
    36	/**
    37	 * A highly enchanted item is held to be beyond the office's ordinary means of
    38	 * restoration, so MHPCO reimburses only half of such a damage.
    39	 */
    40	const HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
    41	
    42	/** Dragon-forged goods are the office's pride; it reimburses them in full. */
    43	const FULLY_REIMBURSED_MATERIAL = "dragon";
    44	
    45	/**
    46	 * The office's register of reimbursement clauses. Each entry is an independent
    47	 * ruling: a further clause is added here, and the property or share of an
    48	 * existing one is revised here, without touching the deductible or the cap.
    49	 */
    50	const REIMBURSEMENT_CLAUSES: readonly ReimbursementClause[] = [
    51	  {
    52	    appliesTo: (damagedItem) =>
    53	      (damagedItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT,
    54	    share: HALF_SHARE,
    55	  },
    56	  {
    57	    appliesTo: (damagedItem) => damagedItem.material === FULLY_REIMBURSED_MATERIAL,
    58	    share: FULL_SHARE,
    59	  },
    60	];
    61	
    62	/**
    63	 * The share of a damage amount MHPCO accepts before taking its deductible.
    64	 *
    65	 * When several clauses apply at once the office grants the least generous of
    66	 * them — a dragon-forged sword of enchantment 9 is reimbursed at half, not in
    67	 * full — and an item no clause speaks to is reimbursed in full.
    68	 */
    69	function acceptedShare(damagedItem: Item): number {
    70	  const shares = REIMBURSEMENT_CLAUSES.filter((clause) => clause.appliesTo(damagedItem)).map(
    71	    (clause) => clause.share,
    72	  );
    73	  return Math.min(FULL_SHARE, ...shares);
    74	}
    75	
    76	/**
    77	 * MHPCO will never pay out more than twice what a policy insures in total,
    78	 * however many claims are made against it.
    79	 */
    80	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    81	
    82	/** The total MHPCO is willing to pay out over the life of a policy. */
    83	export function payoutCap(insuranceSum: number): number {
    84	  return insuranceSum * CAP_MULTIPLE_OF_INSURANCE_SUM;
    85	}
    86	
    87	/** How much of a reimbursement the cap lets through, and what is left of it. */
    88	export interface CappedPayout {
    89	  readonly payout: number;
    90	  readonly remainingCap: number;
    91	}
    92	
    93	/**
    94	 * Holds a reimbursement to what the policy's cap still allows: the office pays
    95	 * the lesser of what it owes and what its cap still permits, and whatever is
    96	 * left of the cap stands available to later claims against the same policy.
    97	 */
    98	export function capPayout(reimbursement: number, remainingCap: number): CappedPayout {
    99	  const payout = Math.min(reimbursement, remainingCap);
   100	  return { payout, remainingCap: remainingCap - payout };
   101	}
   102	
   103	/** MHPCO deducts a fixed excess from every damage event it settles. */
   104	const DEDUCTIBLE_G = 100;
   105	
   106	/**
   107	 * What MHPCO reimburses for a single damaged item: the share of the damage its
   108	 * clauses accept, less the deductible it keeps on every damage event.
   109	 */
   110	export function damageReimbursement(damage: Damage, damagedItem: Item): number {
   111	  if (damage.amount < 0) {
   112	    throw new Error(`a damage cannot be worth less than nothing: ${damage.amount}`);
   113	  }
   114	  return damage.amount * acceptedShare(damagedItem) - DEDUCTIBLE_G;
   115	}
   116	
   117	/**
   118	 * What MHPCO owes for a whole damage report, before its cap is applied: the
   119	 * office settles a report damage entry by damage entry and owes the sum, so a
   120	 * dragon attack on a sword and an amulet costs the office two deductibles, not
   121	 * one. Which insured item an entry refers to is a coverage question the caller
   122	 * answers; this ruling only knows that entries are settled one by one.
   123	 */
   124	export function incidentReimbursement(
   125	  incident: Incident,
   126	  insuredItemFor: (damage: Damage) => Item,
   127	): number {
   128	  return incident.damages.reduce(
   129	    (total, damage) => total + damageReimbursement(damage, insuredItemFor(damage)),
   130	    0,
   131	  );
   132	}
