     1	/**
     2	 * Which insured item a damage entry is claiming against.
     3	 *
     4	 * This module owns one ruling of the office's: how a damage report is matched
     5	 * to the things a policy actually covers. Two decisions live here, and they are
     6	 * the office's to revise independently of how a claim is settled — what makes
     7	 * an insured item answer to a damage entry, and whether one insured item can be
     8	 * claimed for more than once in a single report.
     9	 *
    10	 * It is kept apart from the claims rulings because those price a damage once
    11	 * the damaged item is known; this one only decides *which* item that is. It is
    12	 * kept apart from the price list because that says what MHPCO insures at all,
    13	 * while this says how many of it *this* policy covers.
    14	 */
    15	
    16	import { type Damage } from "./claims.js";
    17	import { type Item } from "./item.js";
    18	
    19	/**
    20	 * Whether an insured item is one a damage entry can be claiming against. MHPCO
    21	 * identifies the damaged thing by its type alone: the report names what kind of
    22	 * item was damaged, and any insured item of that kind answers to it.
    23	 */
    24	function answersTo(insured: Item, damage: Damage): boolean {
    25	  return insured.type === damage.itemType;
    26	}
    27	
    28	/**
    29	 * Matches the damage entries of one report to the items a policy covers.
    30	 *
    31	 * A damaged item is claimed for once: two entries of the same type need two
    32	 * insured items of that type, so the matcher sets each item aside as it is
    33	 * claimed. A report naming more of a type than the policy covers — or a type it
    34	 * does not cover at all — is one the office refuses outright.
    35	 */
    36	export function coverageOf(insuredItems: readonly Item[]): (damage: Damage) => Item {
    37	  const unclaimed = [...insuredItems];
    38	  return (damage) => {
    39	    const index = unclaimed.findIndex((insured) => answersTo(insured, damage));
    40	    if (index === -1) {
    41	      throw new Error(`the policy does not cover a further item of type "${damage.itemType}"`);
    42	    }
    43	    const [claimed] = unclaimed.splice(index, 1);
    44	    return claimed;
    45	  };
    46	}
