     1	/**
     2	 * MHPCO's risk rating of a single insured item.
     3	 *
     4	 * This module owns one underwriting policy: which properties of an item the
     5	 * office considers risky, and what surcharge each of those risks carries. Such
     6	 * a risk surcharge is always charged on the base premium of the affected item
     7	 * alone, never on the policy total — that is what makes it item-specific and
     8	 * keeps it apart from the policy-wide modifiers that depend on the customer's
     9	 * history rather than on the item.
    10	 */
    11	
    12	import { itemBasePremium } from "./price-list.js";
    13	import { type Item } from "./item.js";
    14	
    15	const PERCENT = 100;
    16	
    17	/** A risky property of an item, and the surcharge MHPCO charges for it. */
    18	interface RiskRating {
    19	  readonly appliesTo: (item: Item) => boolean;
    20	  readonly surchargePercent: number;
    21	}
    22	
    23	/**
    24	 * The office's register of item risks. Each entry is an independent ruling:
    25	 * further risks are added here, and the rate of an existing one is revised
    26	 * here, without touching how a premium is assembled.
    27	 */
    28	const HIGHLY_ENCHANTED_FROM = 5;
    29	
    30	const RISK_RATINGS: readonly RiskRating[] = [
    31	  { appliesTo: (item) => item.cursed === true, surchargePercent: 50 },
    32	  {
    33	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGHLY_ENCHANTED_FROM,
    34	    surchargePercent: 30,
    35	  },
    36	];
    37	
    38	/** The total item-specific risk surcharge MHPCO charges for one item. */
    39	export function itemRiskSurcharge(item: Item): number {
    40	  const basePremium = itemBasePremium(item);
    41	  return RISK_RATINGS.filter((rating) => rating.appliesTo(item)).reduce(
    42	    (total, rating) => total + (basePremium * rating.surchargePercent) / PERCENT,
    43	    0,
    44	  );
    45	}
    46	
    47	/** The item-specific risk surcharges of all items a policy covers. */
    48	export function itemRiskSurcharges(items: readonly Item[]): number {
    49	  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
    50	}
===== src/customer-standing.ts =====
     1	/**
     2	 * MHPCO's rating of a policy as a whole, as opposed to the items on it.
     3	 *
     4	 * This module owns one underwriting policy: the modifiers the office charges or
     5	 * credits on the *policy* base premium — the sum of all item base premiums —
     6	 * rather than on any single item. They turn on the customer's standing with the
     7	 * office and on the office's own assessment habits, not on what is insured,
     8	 * which is what keeps them apart from the item-specific risk surcharges.
     9	 *
    10	 * The processing fee is deliberately not here: it is a flat charge added after
    11	 * every modifier, not a rating of the policy base premium.
    12	 */
    13	
    14	import { type Customer } from "./customer.js";
    15	
    16	const PERCENT = 100;
    17	
    18	/**
    19	 * A policy-wide modifier: when the office applies it, and the percentage of the
    20	 * policy base premium it moves. A positive rate is a surcharge the customer
    21	 * owes, a negative rate a discount the office grants.
    22	 */
    23	interface PolicyModifier {
    24	  readonly appliesTo: (customer: Customer) => boolean;
    25	  readonly ratePercent: number;
    26	}
    27	
    28	/**
    29	 * Every item in a quote is treated as a first insurance regardless of customer
    30	 * history, so the initial assessment surcharge is charged on every policy.
    31	 */
    32	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
    33	
    34	/**
    35	 * A long-standing customer is one who has been with MHPCO for 2 years or more;
    36	 * the office credits their loyalty against the policy base premium.
    37	 */
    38	const LONG_STANDING_FROM_YEARS = 2;
    39	const LOYALTY_DISCOUNT_PERCENT = -20;
    40	
    41	/**
    42	 * Every contract after the customer's first is a follow-up contract; the office
    43	 * credits the customer's return against the policy base premium.
    44	 */
    45	const FIRST_CONTRACT_COUNT = 1;
    46	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
    47	
    48	/**
    49	 * The office's register of policy-wide modifiers. Each entry is an independent
    50	 * ruling: a further modifier is added here, and the rate of an existing one is
    51	 * revised here, without touching how a premium is assembled.
